examples.code:
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::stringbuf buffer{"42", std::ios::in | std::ios::out};
    assert(buffer.view() == "42");
    auto allocator = buffer.get_allocator();
    (void)allocator;
    assert(buffer.sbumpc() == '4');
    assert(buffer.sputbackc('4') == '4');
    std::stringbuf other{"73"};
    std::swap(buffer, other);
    assert(buffer.str() == "73");
}
